27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type Result = QuoteResult | ClaimResult;
37	
38	export interface QuoteResult {
39	  premium: number;
40	}
41	
42	export interface ClaimResult {
43	  payout: number;
44	  remainingCap: number;
45	}
46	
47	export interface ScenarioResult {
48	  results: Result[];
49	}
50	
51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
53	const BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	
62	const policyBasePremium = (items: Item[]): number =>
63	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
64	
65	// Premiums round up, in the MHPCO's favour. The surcharge is added as a
66	// separate term rather than folded into a `base * 1.1` factor, which is not
67	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
68	const quotePremium = (items: Item[]): number => {
69	  const base = policyBasePremium(items);
70	  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE);
71	};
72	
73	const quote = (step: QuoteStep): QuoteResult => ({
74	  premium: quotePremium(step.items),
75	});
76	
77	const runStep = (step: Step): Result => {
78	  switch (step.op) {
79	    case "quote":
80	      return quote(step);
81	    default:
82	      throw new Error(`unsupported step: ${step.op}`);
83	  }
84	};
85	
86	export const runScenario = (scenario: Scenario): ScenarioResult => ({
87	  results: scenario.steps.map(runStep),
88	});
